// Each handler approves a request up to its own limit;
// otherwise it passes the request to the next handler.
VisualChain approvals = new VisualChain("approvals");
approvals.addHandler("TeamLead", 1_000)
         .addHandler("Manager", 10_000);

approvals.handle("server", 25_000);          // nobody can approve it yet
approvals.addHandler("Director", 100_000);   // extend the chain

Integer approvedBy = approvals.handle("server", 25_000);
System.out.println("Approved with limit: " + approvedBy);

// Each handler approves a request up to its own limit;
// otherwise it passes the request to the next handler.
