abstract class Handler {
    protected Handler next;

    void setNext(Handler next) {
        this.next = next;
    }

    void handle(Request request) {
        if (canHandle(request)) {
            process(request);
        }
    }

    protected abstract boolean canHandle(Request request);

    protected abstract void process(Request request);
}

// Each handler approves a request up to its own limit;
// otherwise it passes the request to the next handler.
VisualChain approvals = new VisualChain("approvals");
approvals.addHandler("Director", 100_000)
         .addHandler("TeamLead", 1_000);

Integer small = approvals.handle("laptop", 800);
Integer huge = approvals.handle("datacenter", 500_000);

System.out.println(small + " " + huge);
